
/*
 * pcfg_sample.c - Temperature-controlled probabilistic sampler
 *
 * Samples passwords from the trained grammar without enumerating all
 * candidates. Each password is generated by:
 *
 *   1. Sample a base structure weighted by prob^(1/τ)
 *   2. For each slot, sample a terminal from the trained GrammarEntryList
 *      weighted by prob^(1/τ), then sample a value uniformly within
 *      that entry's value set (all values in an entry share the same prob)
 *   3. For A slots with no trained data, fall back to OMEN Markov generation
 *      with temperature applied to character transition weights
 *   4. Structures containing K or M slots are skipped entirely
 *
 * Temperature τ = 1.0 samples faithfully from the trained distribution.
 * τ > 1.0 flattens the distribution (more novel/exploratory output).
 * τ < 1.0 sharpens it (closer to the most common patterns).
 *
 * Invoked with: pcfg -P -g <grammar_dir> [-n count] [-e temperature]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>
#include <math.h>
#include <time.h>
#include <unistd.h>

#include "pcfg.h"

#define SAMPLE_OUTBUF   (1024 * 1024)
#define SAMPLE_MAXPW    512

/* ---- splitmix64 PRNG ---- */
static uint64_t sm_state;

static inline uint64_t splitmix64(void) {
    uint64_t z = (sm_state += 0x9e3779b97f4a7c15ULL);
    z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
    z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
    return z ^ (z >> 31);
}

/* Uniform [0, n) */
static inline int rand_n(int n) {
    if (n <= 1) return 0;
    return (int)(splitmix64() % (uint64_t)n);
}

/* Uniform double [0, 1) */
static inline double rand_double(void) {
    return (double)(splitmix64() >> 11) * (1.0 / (double)(1ULL << 53));
}

/* ---- OMEN generation (mirrored from pcfg_ahf.c, with temperature) ---- */
typedef struct {
    char *alphabet;
    int   alpha_len;
    int   ngram;
    Pvoid_t ip_levels;
    Pvoid_t cp_levels;
    Pvoid_t ep_levels;
    int ln_levels[32];
} SampleOmen;

static SampleOmen *omen_load_sample(const char *gramdir) {
    SampleOmen *og = calloc(1, sizeof(SampleOmen));
    char path[PCFG_MAXPATH];
    char line[1024];

    snprintf(path, sizeof(path), "%s/Omen/config.txt", gramdir);
    FILE *fp = fopen(path, "r");
    if (!fp) { free(og); return NULL; }
    while (fgets(line, sizeof(line), fp))
        if (strncmp(line, "ngram=", 6) == 0) og->ngram = atoi(line + 6);
    fclose(fp);
    if (og->ngram < 2) og->ngram = 4;

    snprintf(path, sizeof(path), "%s/Omen/alphabet.txt", gramdir);
    fp = fopen(path, "r");
    if (!fp) { free(og); return NULL; }
    if (fgets(line, sizeof(line), fp)) {
        int len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) len--;
        line[len] = '\0';
        og->alphabet = strdup(line);
        og->alpha_len = len;
    }
    fclose(fp);
    if (!og->alphabet || og->alpha_len == 0) { free(og); return NULL; }

    snprintf(path, sizeof(path), "%s/Omen/IP.level", gramdir);
    fp = fopen(path, "r");
    if (fp) {
        while (fgets(line, sizeof(line), fp)) {
            int len = strlen(line);
            while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) len--;
            line[len] = '\0';
            char *tab = strchr(line, '\t');
            if (!tab) continue;
            Word_t *pv;
            JSLI(pv, og->ip_levels, (uint8_t *)(tab + 1));
            *pv = (Word_t)atoi(line);
        }
        fclose(fp);
    }

    snprintf(path, sizeof(path), "%s/Omen/CP.level", gramdir);
    fp = fopen(path, "r");
    if (fp) {
        while (fgets(line, sizeof(line), fp)) {
            int len = strlen(line);
            while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) len--;
            line[len] = '\0';
            char *tab = strchr(line, '\t');
            if (!tab) continue;
            Word_t *pv;
            JSLI(pv, og->cp_levels, (uint8_t *)(tab + 1));
            *pv = (Word_t)atoi(line);
        }
        fclose(fp);
    }

    return og;
}

/*
 * Generate one alpha word via OMEN Markov with temperature.
 *
 * Temperature is applied by converting levels to weights: w = e^(-level/τ)
 * then sampling proportionally. At τ=1.0 this is faithful to the trained
 * distribution. At τ>1.0 the distribution flattens (more variety).
 */
static int omen_sample_word(SampleOmen *og, int target_len, double temp,
                            char *out) {
    if (!og || target_len < og->ngram || target_len > 30) return 0;

    int prefix_len = og->ngram - 1;
    double inv_temp = 1.0 / temp;

    /* Try to find a valid starting prefix */
    for (int attempt = 0; attempt < 300; attempt++) {

        /* Sample start prefix weighted by IP levels */
        /* Build a small candidate pool from random prefixes, pick by weight */
        char prefix[8];
        double total_w = 0.0;
        char pool[16][8];
        double pool_w[16];
        int pool_n = 0;

        for (int t = 0; t < 32 && pool_n < 16; t++) {
            char cand[8];
            for (int i = 0; i < prefix_len; i++)
                cand[i] = og->alphabet[rand_n(og->alpha_len)];
            cand[prefix_len] = '\0';

            Word_t *pv;
            JSLG(pv, og->ip_levels, (uint8_t *)cand);
            int level = pv ? (int)*pv : 10;
            double w = exp(-level * inv_temp);
            if (w > 0.0) {
                memcpy(pool[pool_n], cand, prefix_len + 1);
                pool_w[pool_n] = w;
                total_w += w;
                pool_n++;
            }
        }
        if (pool_n == 0) continue;

        /* Weighted draw from pool */
        double r = rand_double() * total_w;
        double acc = 0.0;
        int chosen = 0;
        for (int i = 0; i < pool_n; i++) {
            acc += pool_w[i];
            if (r <= acc) { chosen = i; break; }
        }
        memcpy(prefix, pool[chosen], prefix_len + 1);

        /* Build word character by character */
        memcpy(out, prefix, prefix_len);
        int pos = prefix_len;
        int ok = 1;

        while (pos < target_len) {
            /* Compute weights for each alphabet char */
            double weights[256];
            double wtotal = 0.0;
            char key[16];

            for (int c = 0; c < og->alpha_len; c++) {
                memcpy(key, out + pos - prefix_len, prefix_len);
                key[prefix_len] = og->alphabet[c];
                key[prefix_len + 1] = '\0';

                Word_t *pv;
                JSLG(pv, og->cp_levels, (uint8_t *)key);
                int level = pv ? (int)*pv : 10;
                double w = exp(-level * inv_temp);
                weights[c] = w;
                wtotal += w;
            }

            if (wtotal <= 0.0) { ok = 0; break; }

            /* Weighted sample */
            double pick = rand_double() * wtotal;
            double acc2 = 0.0;
            int ci = 0;
            for (int c = 0; c < og->alpha_len; c++) {
                acc2 += weights[c];
                if (pick <= acc2) { ci = c; break; }
            }
            out[pos++] = og->alphabet[ci];
        }

        if (!ok || pos != target_len) continue;
        out[pos] = '\0';
        return pos;
    }
    return 0;
}

/* ---- Weighted sampler for a GrammarEntryList ----
 *
 * Builds cumulative weights from entry probabilities scaled by p^(1/τ),
 * draws a random entry, then picks a value uniformly within that entry
 * (all values in an entry share the same probability).
 *
 * Returns NULL if gel is empty.
 */
static const char *sample_terminal(GrammarEntryList *gel, double inv_temp) {
    if (!gel || gel->nentries == 0) return NULL;

    /* Build cumulative weight array on the stack for small nentries,
     * heap for large (grammar entries rarely exceed a few hundred). */
    double *weights = malloc(gel->nentries * sizeof(double));
    if (!weights) return NULL;

    double total = 0.0;
    for (int i = 0; i < gel->nentries; i++) {
        double w = pow(gel->entries[i].prob, inv_temp);
        weights[i] = w;
        total += w;
    }

    const char *result = NULL;
    if (total > 0.0) {
        double r = rand_double() * total;
        double acc = 0.0;
        for (int i = 0; i < gel->nentries; i++) {
            acc += weights[i];
            if (r <= acc) {
                GrammarEntry *ge = &gel->entries[i];
                if (ge->nvalues > 0)
                    result = ge->values[rand_n(ge->nvalues)];
                break;
            }
        }
        /* Fallback to last entry if floating-point overshoot */
        if (!result) {
            GrammarEntry *ge = &gel->entries[gel->nentries - 1];
            if (ge->nvalues > 0)
                result = ge->values[rand_n(ge->nvalues)];
        }
    }

    free(weights);
    return result;
}

/* Look up a GrammarEntryList by type string */
static GrammarEntryList *get_gel_by_type(Grammar grammar, const char *type) {
    Word_t *pv;
    JSLG(pv, grammar, (const uint8_t *)type);
    return pv ? (GrammarEntryList *)*pv : NULL;
}

/* ---- Main sample generation ---- */
int pcfg_sample_generate(const char *gramdir, GenCtx *ctx,
                         int64_t count, double temp) {
    if (pcfg_load(gramdir, ctx) < 0) return 1;

    /* Attach case and leet mask nodes the same way -G generation does, so
     * sampled passwords carry the trained capitalization and leet style. */
    if (!ctx->skip_case)
        add_case_mangling(ctx);
    add_leet_mangling(ctx);

    if (temp <= 0.0) temp = 1.0;
    double inv_temp = 1.0 / temp;

    /* OMEN fallback — optional; if unavailable, A slots without trained
     * terminals will be skipped rather than crashing */
    SampleOmen *og = omen_load_sample(gramdir);
    if (!og)
        fprintf(stderr, "pcfg: sample: no OMEN data, alpha fallback disabled\n");

    fprintf(stderr,
        "pcfg: sample mode: %d structures, τ=%.3f, %" PRId64 " passwords\n",
        ctx->nbases, temp, count);

    /* Seed PRNG from time + pid for non-deterministic output */
    sm_state = (uint64_t)time(NULL) ^ ((uint64_t)getpid() << 32)
               ^ 0xdeadbeefcafeULL;
    /* Warm up */
    for (int i = 0; i < 16; i++) splitmix64();

    /* Pre-compute base structure weights for sampling */
    double *base_weights = malloc(ctx->nbases * sizeof(double));
    if (!base_weights) { fprintf(stderr, "pcfg: sample OOM\n"); return 1; }

    double base_total = 0.0;
    for (int i = 0; i < ctx->nbases; i++) {
        /* Skip structures containing K or M slots */
        int skip = 0;
        for (int j = 0; j < ctx->bases[i].nreplace; j++) {
            char t = ctx->bases[i].replacements[j][0];
            if (t == ST_KEYBOARD || t == ST_MARKOV) { skip = 1; break; }
        }
        if (skip) {
            base_weights[i] = 0.0;
            continue;
        }
        base_weights[i] = pow(ctx->bases[i].prob, inv_temp);
        base_total += base_weights[i];
    }

    if (base_total <= 0.0) {
        fprintf(stderr, "pcfg: sample: no usable base structures\n");
        free(base_weights);
        return 1;
    }

    /* Build cumulative weights for O(log n) structure sampling */
    double *base_cumul = malloc(ctx->nbases * sizeof(double));
    if (!base_cumul) { fprintf(stderr, "pcfg: sample OOM\n"); free(base_weights); return 1; }
    {
        double acc = 0.0;
        for (int i = 0; i < ctx->nbases; i++) {
            acc += base_weights[i];
            base_cumul[i] = acc;
        }
    }
    free(base_weights);

    char *outbuf = malloc(SAMPLE_OUTBUF);
    char *pw = malloc(SAMPLE_MAXPW);
    if (!outbuf || !pw) {
        fprintf(stderr, "pcfg: sample OOM\n");
        return 1;
    }
    int outpos = 0;
    int64_t generated = 0;
    int64_t attempts = 0;

    while (generated < count) {
        attempts++;

        /* Sample a base structure by weight (binary search on cumulative) */
        double r = rand_double() * base_total;
        /* Binary search */
        int lo = 0, hi = ctx->nbases - 1, si = ctx->nbases - 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (base_cumul[mid] < r) lo = mid + 1;
            else { si = mid; hi = mid - 1; }
        }
        BaseStructure *bs = &ctx->bases[si];

        /* Build password slot by slot */
        int pwpos = 0;
        int ok = 1;

        /* We may need the alpha buffer for a preceding C slot */
        int last_alpha_start = -1;
        int last_alpha_len   = 0;

        for (int j = 0; j < bs->nreplace && ok; j++) {
            char *type = bs->replacements[j];
            char tchar = type[0];
            int  tlen  = atoi(type + 1);
            if (tlen < 0) tlen = 0;

            if (tchar == ST_KEYBOARD || tchar == ST_MARKOV) {
                ok = 0;
                break;
            }

            if (tchar == ST_ALPHA || SemLetters[(unsigned char)tchar]) {
                /* Try trained terminals first */
                GrammarEntryList *gel = get_gel_by_type(ctx->grammar, type);
                const char *val = gel ? sample_terminal(gel, inv_temp) : NULL;

                if (val) {
                    int vlen = strlen(val);
                    if (pwpos + vlen >= SAMPLE_MAXPW) { ok = 0; break; }
                    last_alpha_start = pwpos;
                    memcpy(pw + pwpos, val, vlen);
                    pwpos += vlen;
                    last_alpha_len = vlen;
                } else if (og && tlen > 0) {
                    /* OMEN Markov fallback */
                    char word[64];
                    int wlen = omen_sample_word(og, tlen, temp, word);
                    if (wlen <= 0 || pwpos + wlen >= SAMPLE_MAXPW) { ok = 0; break; }
                    last_alpha_start = pwpos;
                    memcpy(pw + pwpos, word, wlen);
                    pwpos += wlen;
                    last_alpha_len = wlen;
                } else {
                    ok = 0;
                }

            } else if (tchar == ST_CASE) {
                /* Apply a sampled case mask to the preceding alpha */
                if (last_alpha_start < 0) { ok = 0; break; }

                GrammarEntryList *gel = get_gel_by_type(ctx->grammar, type);
                const char *mask = gel ? sample_terminal(gel, inv_temp) : NULL;
                if (!mask) { ok = 0; break; }

                /* Apply mask in-place over the alpha bytes already written */
                int mlen = strlen(mask);
                int ai = last_alpha_start;
                int mi = 0;
                while (ai < pwpos && mi < mlen) {
                    uint32_t cp;
                    int n = utf8_decode(pw + ai, pwpos - ai, &cp);
                    if (n == 0) break;
                    uint32_t mapped = (mask[mi] == 'U') ? utf8_to_upper(cp)
                                                        : utf8_to_lower(cp);
                    /* Re-encode in place.  utf8_encode() is wrong here: a
                     * byte that arrived as a lone 0x80-0xFF decodes with
                     * n == 1 and a codepoint >= 0x80, so it would write two
                     * bytes into a one-byte slot and walk over the next
                     * character.  utf8_encode_width() keeps the arrival
                     * width, which is also what the terminal was trained on.
                     * For n >= 2 the width is unchanged either way: every
                     * mapping in utf8_to_upper/lower is +/-0x20, 0x50 or 1
                     * and stays inside its own UTF-8 length class. */
                    utf8_encode_width(pw + ai, mapped, n);
                    ai += n;
                    mi++;
                }

            } else if (tchar == ST_LEET) {
                /* Apply a sampled leet mask to the preceding alpha */
                if (last_alpha_start < 0) { ok = 0; break; }

                GrammarEntryList *gel = get_gel_by_type(ctx->grammar, type);
                const char *lmask = gel ? sample_terminal(gel, inv_temp) : NULL;
                if (!lmask) { ok = 0; break; }

                int mlen = strlen(lmask);
                int aend = last_alpha_start + last_alpha_len;
                int ai = last_alpha_start, mi = 0;
                while (ai < aend && mi < mlen) {
                    uint32_t cp;
                    int n = utf8_decode(pw + ai, aend - ai, &cp);
                    if (n == 0) break;
                    unsigned char lm = (unsigned char)lmask[mi];
                    /* substitute only where the base letter matches */
                    if (lm != '.' && n == 1 &&
                        (uint32_t)leet_fold[lm] == utf8_to_lower(cp))
                        pw[ai] = (char)lm;
                    ai += n;
                    mi++;
                }

            } else if (tchar == ST_DIGIT || tchar == ST_OTHER ||
                       tchar == ST_YEAR  || tchar == ST_CONTEXT ||
                       tchar == ST_DATE) {
                GrammarEntryList *gel = get_gel_by_type(ctx->grammar, type);
                const char *val = gel ? sample_terminal(gel, inv_temp) : NULL;
                if (!val) { ok = 0; break; }
                int vlen = strlen(val);
                if (pwpos + vlen >= SAMPLE_MAXPW) { ok = 0; break; }
                memcpy(pw + pwpos, val, vlen);
                pwpos += vlen;

            } else {
                /* Unknown type — skip structure */
                ok = 0;
            }
        }

        if (!ok || pwpos <= 0) continue;
        pw[pwpos] = '\0';

        /* Emit */
        if (outpos + PCFG_HEXLINE_MAX(pwpos) >= SAMPLE_OUTBUF) {
            write(STDOUT_FILENO, outbuf, outpos);
            outpos = 0;
        }
        outpos += pcfg_emit_line(outbuf + outpos, pw, pwpos);
        generated++;
    }

    if (outpos > 0)
        write(STDOUT_FILENO, outbuf, outpos);

    fprintf(stderr,
        "pcfg: sample: %" PRId64 " passwords in %" PRId64 " attempts (%.1f%% hit rate)\n",
        generated, attempts,
        attempts > 0 ? 100.0 * generated / attempts : 0.0);

    free(outbuf);
    free(pw);
    free(base_cumul);
    return 0;
}
